-- rex_session_manager.lua: the Rex side of `rex-session-manager`.
--
-- Generated by `rex-session-manager init-lua`; regenerate it after the binary
-- moves (a mise upgrade installs it in a new directory). Save it beside your
-- Rex `init.lua` and call `setup` once with your prefix, and optionally the
-- shell new tabs should start:
--
--   require("rex_session_manager").setup("ctrl+a")
--   require("rex_session_manager").setup("ctrl+a", { shell = "/opt/homebrew/bin/fish" })
--
-- The binary owns the session logic: it reads and validates the project
-- presets in `sessions/` beside this file, lists, creates, and destroys
-- sessions through `rex api call`, and builds the menus. Only two things stay
-- in Lua, because only Lua can do them:
--
-- * `rex.ui.pick`, which asks only from inside an action's `run` function and
--   the functions it calls directly. A key-bound closure, a `pcall`/`xpcall`
--   wrapper, a handler registered with `rex.on`, or a function reached through
--   `rex.invoke` gets `nil, "failed"` instead of a prompt, so every `ask` below
--   stays on the action's own stack;
-- * `rex.client.queue("session.select", ...)`, which shows a session in the
--   invoking app after the action returns.
--
-- Every binary call passes `--sessions-dir` and `--marks-dir` explicitly, so
-- the presets are the ones beside this config and the marks land in the same
-- state directory every time. The binary reads both on every call: a preset
-- change needs no `rex config reload`.
--
-- `M.SHELL` is the shell new tabs start, sent as the binary's `--shell` and
-- from there as Rex's `shell` option. Left nil, no shell is sent and Rex starts
-- its own default shell (your login shell), not the Rex app's
-- `Workspace.terminalStartupCommand` preference. `setup`'s options set it; a
-- call made directly on `M.run` may set `M.SHELL` itself.

local NAME = "rex-session-manager"
-- An absolute path: actions run with Rex's restricted PATH
-- (/usr/bin:/bin:/usr/sbin:/sbin), which holds neither Homebrew, mise, nor
-- ~/.cargo/bin.
local BINARY = "/Users/camilo/.cargo/bin/rex-session-manager"
local SESSIONS_DIRECTORY = "sessions"
-- The marks live in state, not in the config. Actions run without
-- XDG_STATE_HOME, so the path is named here instead of left to the binary's
-- environment. Read HOME without failing the config load: a missing HOME
-- surfaces as an error when an action runs.
local MARKS_PATH = (os.getenv("HOME") or "") .. "/.local/state/rex-session-manager"

-- Rex prepends the loaded config's directory to package.path, so the first
-- entry names the directory holding this module.
local function config_directory()
  local entry = package.path:match("^([^;]+)")
  local directory = entry and entry:match("^(.*)%?%.lua$")
  directory = directory and directory:gsub("/+$", "")
  if directory == nil or directory == "" then
    error("cannot locate the Rex config directory from package.path", 0)
  end
  return directory
end

local SESSIONS_PATH = config_directory() .. "/" .. SESSIONS_DIRECTORY

local M = {}

M.SESSIONS_PATH = SESSIONS_PATH

M.MARKS_PATH = MARKS_PATH

-- The shell new tabs start, by path or by name such as "/opt/homebrew/bin/fish".
-- nil leaves the choice to Rex. Set it with `setup(PREFIX, { shell = ... })`,
-- or directly when calling the functions below without `setup`.
M.SHELL = nil

local function fail(message)
  error(message, 0)
end

-- Run the binary with the given arguments and decode its JSON output. A
-- command that prints nothing (`kill`) returns an empty table. Any failure
-- raises the binary's own message plus its exit status.
function M.run(...)
  -- The global arguments first, so the caller's own can follow `--`; `--shell`
  -- goes in only when this module sets a shell.
  local arguments = {
    BINARY,
    "--sessions-dir",
    SESSIONS_PATH,
    "--marks-dir",
    MARKS_PATH,
  }
  if M.SHELL ~= nil then
    arguments[#arguments + 1] = "--shell"
    arguments[#arguments + 1] = M.SHELL
  end
  for index = 1, select("#", ...) do
    arguments[#arguments + 1] = select(index, ...)
  end

  local result, exec_error = rex.exec(arguments)
  if type(result) ~= "table" then
    fail(NAME .. " did not run: " .. tostring(exec_error or result))
  end
  if result.ok ~= true then
    -- The binary already prefixes its messages with its name; keep one.
    local reason = tostring(result.stderr or "")
      :gsub("^" .. NAME:gsub("%-", "%%-") .. ": ", "")
      :gsub("%s+$", "")
    fail(
      ("%s exited %s%s"):format(
        NAME,
        tostring(result.code),
        reason ~= "" and (": " .. reason) or ""
      )
    )
  end

  local output = tostring(result.stdout or "")
  if output:match("^%s*$") then
    return {}
  end
  -- rex.json.decode returns nil plus a reason instead of raising.
  local decoded, reason = rex.json.decode(output)
  if decoded == nil then
    fail(NAME .. " printed invalid JSON: " .. tostring(reason))
  end
  return decoded
end

-- Reuse or create the project's session, then show it in the invoking client.
-- The select is queued, so it runs after the calling action returns.
function M.jump(project)
  local target = M.run("jump", "--", project)
  rex.client.queue("session.select", {
    session_id = target.session_id,
    window_id = target.window_id,
  })
  return target
end

-- Go to a mark: its recorded session while it runs, else the session labelled
-- with its name, else a new session from its preset. The extra arguments are
-- the binary's own selector: `--position N` from the q/w/e/r keys, or `--` and
-- the name the marks menu returned.
function M.jump_mark(...)
  local target = M.run("jump-mark", ...)
  rex.client.queue("session.select", {
    session_id = target.session_id,
    window_id = target.window_id,
  })
  return target
end

local MODES = { projects = true, active = true, close = true, save = true, delete = true }

local MODE_ARGS = {
  type = "object",
  properties = {
    mode = {
      type = "string",
      enum = { "projects", "active", "close", "save", "delete" },
    },
  },
  required = { "mode" },
  additionalProperties = false,
}

-- The only call that asks the person. It must run on the action's own stack:
-- see the note at the top of this file before moving it behind an `invoke` or
-- a `pcall`. `menu` is the binary's `{title, confirm, items}`, passed as is.
local function ask(mode, menu)
  local id, why, detail = rex.ui.pick{
    title = menu.title,
    confirm = menu.confirm,
    items = menu.items,
  }
  if id ~= nil then
    return id
  end
  if why == "cancelled" then
    return nil
  end
  fail(
    "could not show the " .. mode .. " menu: "
      .. tostring(why or "unknown")
      .. (detail and (" — " .. detail) or "")
  )
end

local function needs_client(ctx, action)
  -- The prompt is delivered through this client, and session.select acts on
  -- it. Guessing a client could act on another app.
  if ctx.client_id == nil or ctx.client_id == "" then
    fail(action .. " needs the invoking client; run it from a Rex shortcut or pass -C")
  end
end

local function session_manager(ctx, args)
  local mode = args.mode
  if not MODES[mode] then
    fail("unknown session manager mode: " .. tostring(mode))
  end
  needs_client(ctx, "session_manager")

  local menu = M.run("menu", mode)
  if menu.items == nil or #menu.items == 0 then
    return {}
  end
  local choice = ask(mode, menu)
  if choice == nil then
    return {}
  end

  if mode == "projects" then
    M.jump(choice)
  elseif mode == "active" then
    -- pcall keeps the native message free of a Lua file:line prefix. It wraps
    -- only the queue, never the prompt.
    local ok, err = pcall(rex.client.queue, "session.select", { session_id = choice })
    if not ok then
      fail(tostring(err))
    end
  elseif mode == "close" then
    -- Choosing the row is the whole decision: the binary destroys exactly
    -- this ID, never a substitute.
    M.run("kill", "--", choice)
  elseif mode == "delete" then
    -- The first call removes nothing: it locates the preset and returns the
    -- binary's confirmation menu. Running sessions are never touched.
    local target = M.run("delete", "--", choice)
    if ask("delete", target.menu) ~= "delete" then
      return {}
    end
    M.run("delete", "--confirmed", "--", choice)
  else
    -- A new preset is written at once. An existing one is only reported, with
    -- the binary's overwrite menu; replacing it passes the confirmed name, so
    -- a session renamed meanwhile is refused instead of replacing another.
    local saved = M.run("save", "--", choice)
    if saved.status == "exists" then
      if ask("overwrite", saved.menu) ~= "overwrite" then
        return {}
      end
      M.run("save", "--overwrite", saved.name, "--", choice)
    end
  end
  return {}
end

-- Mark the session the key press names; when it names none, ask which running
-- session to mark. The binary writes the preset first when the session has
-- none, and never duplicates a mark.
local function mark_session(ctx)
  local session_id = ctx.session_id
  if session_id == nil or session_id == "" then
    needs_client(ctx, "mark_session")
    local menu = M.run("menu", "save")
    if menu.items == nil or #menu.items == 0 then
      return {}
    end
    session_id = ask("mark", menu)
    if session_id == nil then
      return {}
    end
  end
  M.run("mark", "--", session_id)
  return {}
end

-- The marks menu. Choosing a mark jumps to it; the binary's `Move…` row (id
-- `move_id`) and `Unmark…` row (id `unmark_id`) open their own prompts. Neither
-- id ever equals a mark's name. Escape at any prompt changes nothing.
local function marks_menu(ctx)
  needs_client(ctx, "marks_menu")

  local menu = M.run("menu", "marks")
  if menu.items == nil or #menu.items == 0 then
    return {}
  end
  local choice = ask("marks", menu)
  if choice == nil then
    return {}
  end

  if choice == menu.move_id then
    local marked = M.run("menu", "move")
    if marked.items == nil or #marked.items == 0 then
      return {}
    end
    local name = ask("move", marked)
    if name == nil then
      return {}
    end
    local choose = M.run("move", "--", name)
    local position = ask("move", choose.menu)
    if position == nil then
      return {}
    end
    M.run("move", "--to", position, "--", name)
    return {}
  end

  if choice == menu.unmark_id then
    local marked = M.run("menu", "unmark")
    if marked.items == nil or #marked.items == 0 then
      return {}
    end
    local name = ask("unmark", marked)
    if name == nil then
      return {}
    end
    M.run("unmark", "--", name)
    return {}
  end

  M.jump_mark("--", choice)
  return {}
end

-- Register the actions and their default keys. Call once with your prefix,
-- and optionally the shell new tabs should start:
--
--   require("rex_session_manager").setup("ctrl+a", { shell = "/opt/homebrew/bin/fish" })
--
-- `options.shell` is a path or a name such as "/opt/homebrew/bin/fish". Left
-- out, Rex starts its own default shell, your login shell. Bind `jump_project`
-- to your own projects, for example:
--
--   rex.bind(PREFIX .. ">n", "jump_project", { project = "nvim" })
function M.setup(PREFIX, options)
  if options ~= nil then
    if type(options) ~= "table" then
      fail(
        "setup takes an options table as its second argument, for example "
          .. 'setup(PREFIX, { shell = "/opt/homebrew/bin/fish" })'
      )
    end
    if options.shell ~= nil then
      if type(options.shell) ~= "string" or options.shell == "" then
        fail(
          "setup: shell must be a non-empty string, the shell new tabs start, "
            .. 'for example "/opt/homebrew/bin/fish"'
        )
      end
      M.SHELL = options.shell
    end
  end

  rex.action{
    name = "session_manager",
    title = "Session Manager",
    description = "Browse project presets, switch running sessions, close one at once, save one as a preset, or delete a preset.",
    category = "Sessions",
    keywords = "projects presets active close save delete picker",
    args = MODE_ARGS,
    run = session_manager,
  }
  rex.action{
    name = "jump_project",
    title = "Jump to Project",
    description = "Open the project preset from " .. SESSIONS_PATH .. ", reusing its session when one is running.",
    category = "Sessions",
    args = { project = "string" },
    run = function(_, args)
      local target = M.jump(args.project)
      return { session_id = target.session_id }
    end,
  }
  rex.action{
    name = "mark_session",
    title = "Mark Session",
    description = "Mark the current session as one of q, w, e, r, saving it as a preset first when it has none.",
    category = "Sessions",
    keywords = "mark harpoon add pin q w e r",
    run = mark_session,
  }
  rex.action{
    name = "marks_menu",
    title = "Marks Menu",
    description = "Jump to a mark saved in " .. MARKS_PATH .. "/marks.json, move one, or remove one.",
    category = "Sessions",
    keywords = "marks harpoon jump move unmark remove",
    run = marks_menu,
  }
  rex.action{
    name = "jump_mark",
    title = "Jump to Mark",
    description = "Jump to the mark at a position: its running session, its preset, or a new session from that preset.",
    category = "Sessions",
    keywords = "marks harpoon position q w e r",
    args = { position = "string" },
    run = function(_, args)
      local target = M.jump_mark("--position", args.position)
      return { session_id = target.session_id }
    end,
  }

  rex.bind(PREFIX .. ">s", "session_manager", { mode = "projects" })
  rex.bind(PREFIX .. ">ctrl+s", "session_manager", { mode = "active" })
  rex.bind(PREFIX .. ">ctrl+k", "session_manager", { mode = "close" })
  rex.bind(PREFIX .. ">ctrl+w", "session_manager", { mode = "save" })
  rex.bind(PREFIX .. ">ctrl+d", "session_manager", { mode = "delete" })
  rex.bind(PREFIX .. ">ctrl+h>a", "mark_session")
  rex.bind(PREFIX .. ">ctrl+h>m", "marks_menu")
  rex.bind(PREFIX .. ">ctrl+h>ctrl+m", "marks_menu")
  -- Marks 1-4; the marks menu reaches the rest. The position travels as a
  -- string, like every other action argument.
  for position, key in ipairs({ "q", "w", "e", "r" }) do
    rex.bind(PREFIX .. ">" .. key, "jump_mark", { position = tostring(position) })
  end
end

return M
